<?php $title='Project'; require __DIR__.'/../layouts/header.php'; ?>
<div class="pagehead"><div><h1><?=e($project['name']??'Project')?></h1><p><?=e($project['status']??'')?> · <?=e($project['start_date']??'')?> → <?=e($project['end_date']??'')?></p></div><a class="secondary" href="<?=route('project.edit',['id'=>$project['id']])?>">Edit</a></div>
<section class="grid two"><div class="panel"><h2>Lifecycle</h2><p>Status <span class="badge"><?=e($project['status'])?></span></p><p>Recurring: <?=!empty($project['is_recurring'])?'Yes — every '.e($project['recurring_cycle_days']).' days':'No'?></p></div><div class="panel"><h2>Workflow</h2><?php if(!$project['workflow']): ?><p class="muted">No workflow instance is available.</p><?php else: ?><?php foreach($project['steps'] as $step): ?><div class="step"><strong><?=e($step['title'])?></strong><span class="badge"><?=e($step['status'])?></span><?php if($step['status']==='not_started'): ?><form method="post" action="<?=route('workflow.step.complete',['id'=>$step['id']])?>" style="margin-top:8px"><?=csrf_field()?><button class="secondary">Complete step</button></form><?php endif; ?></div><?php endforeach; ?><?php if($project['workflow']['status']!=='completed'): ?><form method="post" action="<?=route('workflow.complete',['id'=>$project['workflow']['id']])?>" style="margin-top:12px"><?=csrf_field()?><button class="primary" data-confirm="Complete this workflow?">Complete workflow</button></form><?php else: ?><div class="success">Workflow complete.</div><?php endif; ?><?php endif; ?></div></section>
<form method="post" action="<?=route('project.status',['id'=>$project['id']])?>" class="panel"><?=csrf_field()?><h2>Change status</h2><div class="toolbar"><select name="status"><?php foreach(['draft','upcoming','open','completed','closed','expired','cancelled','on_hold'] as $st): ?><option <?=$project['status']===$st?'selected':''?>><?=$st?></option><?php endforeach; ?></select><button class="secondary">Update status</button></div></form>
<?php require __DIR__.'/../layouts/footer.php'; ?>